\begin{definition}[Connection Laplacian]
\dcref{ch2:1.1}
\label{topping:notn-rough-laplacian}
\source{topping:page-0026}
\group{topping-background}


The connection Laplacian of a tensor field $A$ is
\[
\Delta A:=\tr_{12}\nabla^2A.
\]
\end{definition}

